import os, re

def load():
    d = os.path.normpath(os.environ.get('RLM_SESSION_DIR', ''))
    if not d:
        print("No RLM_SESSION_DIR found")
        return {}
    # Try different paths for session file
    base = os.path.basename(d)
    try:
        t = open(d + '/../../sessions/' + base + '.jsonl').read()
    except:
        pass
    else:
        G = {}
        for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n', t):
            k, h, w = m[1], int(m[2]), int(m[3])
            rows_content = t[m.end():].split('\n')[:h]
            if len(rows_content) == h and all(len(r) == w for r in rows_content):
                rows = [r.split() for r in rows_content if r.strip()]
                if all(all(x.isdigit() for x in row) for row in rows):
                    G[k] = [[int(x) for x in row] for row in rows]
        return G

G = load()
print("Loaded grids:", sorted(G.keys()))
for k in G:
    print(f"\n{G[k]}")

